"""Count the handler shapes a widened silent-except gate would flag."""
import ast
import sys
from collections import Counter
from pathlib import Path

sys.path.insert(0, ".")
from scripts.check_project_hygiene import SKIP_DIRS, ALLOW_MARKER  # noqa: E402

BROAD = {"Exception", "BaseException"}


def shape(node, source_lines):
    if len(node.body) != 1:
        return None
    stmt = node.body[0]
    kind = type(stmt).__name__
    if kind not in ("Pass", "Return", "Continue", "Break"):
        return None
    if isinstance(node.type, ast.Name):
        name = node.type.id
    elif node.type is None:
        name = "<bare>"
    else:
        name = ast.unparse(node.type)
    broad = name in BROAD or name == "<bare>"
    # Already annotated lines are exempt from the gate.
    line = source_lines[node.lineno - 1] if node.lineno <= len(source_lines) else ""
    allowed = bool(ALLOW_MARKER.search(line))
    return (("broad" if broad else "typed"), kind, allowed, name)


def walk(root):
    counts = Counter()
    examples = {}
    for path in root.rglob("*.py"):
        if {p.name for p in path.parents} & SKIP_DIRS or any(d in path.parts for d in SKIP_DIRS):
            continue
        try:
            source = path.read_text(encoding="utf-8")
            tree = ast.parse(source)
        except (OSError, SyntaxError):
            continue
        lines = source.splitlines()
        for node in ast.walk(tree):
            if isinstance(node, ast.ExceptHandler):
                got = shape(node, lines)
                if got:
                    key = (got[0], got[1], got[2])
                    counts[key] += 1
                    examples.setdefault(key, f"{path.relative_to(root)}:{node.lineno} except {got[3]}: {got[1].lower()}")
    return counts, examples


for label, root in [("AIKIT", Path("scripts")), *((p.name.upper(), p) for p in sorted(Path("projects").iterdir()) if p.is_dir())]:
    counts, examples = walk(root)
    total = sum(counts.values())
    unannotated = sum(n for (t, k, allowed), n in counts.items() if not allowed)
    print(f"{label}: {total} single-statement handlers, {unannotated} unannotated")
    for key, n in sorted(counts.items(), key=lambda kv: -kv[1]):
        t, k, allowed = key
        print(f"   {n:3d} {t:5s} except -> {k:8s} {'(annotated)' if allowed else ''}  e.g. {examples[key]}")

